<?php if ($audit !== null): ?>
<h3 class="overview-subheading">Audit findings on pages with search demand</h3><p class="muted small">Completed <?= $view->e($audit->finishedAt ?? $audit->createdAt) ?> UTC · <?= $audit->pagesCrawled ?> crawled pages · <?= $audit->errors ?> errors / <?= $audit->warnings ?> warnings. Search evidence: <?= $view->e($evidence['range']->fromString()) ?> – <?= $view->e($evidence['range']->toString()) ?>.</p>
