<?php if ($evidence['backlinks'] !== []): $current = $evidence['backlinks'][0]; $profile = $current['profiles'][$own] ?? null; $previous = $evidence['backlinks'][1] ?? null; $before = $previous['profiles'][$own] ?? null; ?>
<?php if ($profile !== null): ?><h3 class="overview-subheading">Backlink movement</h3><p><strong><?= $profile->referringDomains === null ? 'Unavailable' : number_format($profile->referringDomains) ?></strong> referring domains · <strong><?= $profile->backlinks === null ? 'Unavailable' : number_format($profile->backlinks) ?></strong> backlinks</p><p class="muted small">Saved <?= $view->e($current['date']) ?>.<?php if ($before !== null): ?> Net change vs <?= $view->e($previous['date']) ?>: <?= $profile->referringDomains !== null && $before->referringDomains !== null ? sprintf('%+d', $profile->referringDomains - $before->referringDomains) : 'unavailable' ?> referring domains / <?= $profile->backlinks !== null && $before->backlinks !== null ? sprintf('%+d', $profile->backlinks - $before->backlinks) : 'unavailable' ?> backlinks.<?php endif; ?></p><?php endif; ?>
