<details class="overview-research-group"><summary><?= $view->e($label) ?> referring-domain sample<span class="muted small"><?= count($domains) ?> records</span></summary><p class="muted small">Fetched <?= $view->e($result->fetchedAt) ?> UTC · provider's recent 30-day sample, maximum 200 records.</p><ul class="overview-evidence-list"><?php foreach (array_slice($domains, 0, 3) as $domain): ?><li><?= $view->e($domain->domain) ?><span class="overview-cell-note"><?= $domain->backlinks === null ? 'Backlink count unavailable' : number_format($domain->backlinks) . ' backlinks' ?> · <?= $view->e($key === 'lost' ? ($domain->lostDate ?? 'loss date unavailable') : ($domain->firstSeen ?? 'first-seen date unavailable')) ?></span></li><?php endforeach; ?></ul></details>
